package net.civeira.phylax.features.access.userconsentedscopes.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userconsentedscopes.domain.UserConsentedScopes;
import net.civeira.phylax.features.access.userconsentedscopes.domain.event.UserConsentedScopesEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserConsentedScopesEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserConsentedScopesEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserConsentedScopes entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
